### `compaction.go`

```go
// Package quorumcompaction implements a safe compaction planner for a
// replicated, multi-version key-value store in which concurrent writes,
// tombstones and long-lived snapshot readers are all active.
//
// The central safety property is:
//
//	A stored record S may be physically reclaimed iff every permitted read
//	quorum of size R is guaranteed to contain at least one replica that still
//	holds a record *strictly greater* than S.
//
// With M read-eligible replicas this is equivalent to requiring that at least
// M-R+1 eligible replicas hold a greater record.  The planner decides this
// per record, in descending version order, against the set of records that are
// actually being retained (not merely the pre-compaction state), which makes
// the proof compositional.  Tombstones are ordinary records under this rule,
// so "latest is a tombstone" can never be reclaimed (no greater record exists)
// and resurrection is impossible.
package quorumcompaction

import (
	"sort"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// Version vectors and stamps
// ---------------------------------------------------------------------------

// ReplicaID identifies a replica.
type ReplicaID string

// VersionVector is a per-replica logical clock.  A missing entry means zero.
type VersionVector map[ReplicaID]uint64

// Clone returns a deep copy.
func (v VersionVector) Clone() VersionVector {
	c := make(VersionVector, len(v))
	for k, x := range v {
		c[k] = x
	}
	return c
}

// Sum is the total logical work in the vector.  It strictly increases under
// componentwise dominance and is the primary key of the total order below.
func (v VersionVector) Sum() uint64 {
	var s uint64
	for _, x := range v {
		s += x
	}
	return s
}

// Dominates reports whether v[r] >= o[r] for every r (componentwise >=).
func (v VersionVector) Dominates(o VersionVector) bool {
	for r := range v {
		if v[r] < o[r] {
			return false
		}
	}
	for r := range o {
		if v[r] < o[r] {
			return false
		}
	}
	return true
}

// Merge returns the componentwise maximum.
func (v VersionVector) Merge(o VersionVector) VersionVector {
	c := v.Clone()
	for r, x := range o {
		if x > c[r] {
			c[r] = x
		}
	}
	return c
}

// Equal reports componentwise equality (zero == absent).
func (v VersionVector) Equal(o VersionVector) bool {
	return v.Dominates(o) && o.Dominates(v)
}

// String renders the vector in a canonical, order-independent form.
func (v VersionVector) String() string {
	keys := make([]string, 0, len(v))
	for k := range v {
		keys = append(keys, string(k))
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		b.WriteString(k)
		b.WriteByte('=')
		b.WriteString(strconv.FormatUint(v[ReplicaID(k)], 10))
		b.WriteByte(',')
	}
	return b.String()
}

// Stamp labels one write version.  VV is the writer's full version vector at
// write time; Origin/Seq break ties between concurrent versions.
type Stamp struct {
	Origin ReplicaID
	Seq    uint64
	VV     VersionVector
}

// Compare defines the total order used for last-writer-wins resolution.
//
// It refines version-vector dominance (if a dominates b then a > b), because
// dominance strictly increases Sum.  Sum, then Origin, then Seq form a
// genuine total order, avoiding the non-transitivity that arises when a
// partial order is patched with a tie-break.
func (s Stamp) Compare(o Stamp) int {
	a, b := s.VV.Sum(), o.VV.Sum()
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	if s.Origin != o.Origin {
		if s.Origin < o.Origin {
			return -1
		}
		return 1
	}
	if s.Seq < o.Seq {
		return -1
	}
	if s.Seq > o.Seq {
		return 1
	}
	return 0
}

// Equal reports whether two stamps are the same total-order element.
func (s Stamp) Equal(o Stamp) bool { return s.Compare(o) == 0 }

// ID is a canonical identity for a write version.
func (s Stamp) ID() string {
	return string(s.Origin) + "@" + strconv.FormatUint(s.Seq, 10) + "#" + s.VV.String()
}

func (s Stamp) String() string { return s.ID() }

// ---------------------------------------------------------------------------
// Records and stores
// ---------------------------------------------------------------------------

// Record is a single key version.  Tombstone records suppress older values.
type Record struct {
	Key   string
	Value []byte
	Tomb  bool
	Stamp Stamp
}

// Size is the approximate on-disk footprint, including fixed stamp overhead.
func (r Record) Size() int { return len(r.Key) + len(r.Value) + 48 }

// Clone deep-copies the record.
func (r Record) Clone() Record {
	r.Value = append([]byte(nil), r.Value...)
	r.Stamp = Stamp{Origin: r.Stamp.Origin, Seq: r.Stamp.Seq, VV: r.Stamp.VV.Clone()}
	return r
}

// Store holds all retained versions of each key, newest first.
type Store struct {
	Records map[string][]Record
}

// NewStore returns an empty store.
func NewStore() *Store { return &Store{Records: map[string][]Record{}} }

// Put inserts or replaces a record, keeping the slice sorted descending.
func (s *Store) Put(r Record) {
	lst := s.Records[r.Key]
	id := r.Stamp.ID()
	for i := range lst {
		if lst[i].Stamp.ID() == id {
			lst[i] = r.Clone()
			return
		}
	}
	lst = append(lst, r.Clone())
	sort.SliceStable(lst, func(i, j int) bool {
		return lst[i].Stamp.Compare(lst[j].Stamp) > 0
	})
	s.Records[r.Key] = lst
}

// Max returns the newest record for key, if any.
func (s *Store) Max(key string) (Record, bool) {
	lst := s.Records[key]
	if len(lst) == 0 {
		return Record{}, false
	}
	return lst[0], true
}

// Clone returns a deep copy of the store.
func (s *Store) Clone() *Store {
	c := NewStore()
	for k, lst := range s.Records {
		cp := make([]Record, len(lst))
		for i, r := range lst {
			cp[i] = r.Clone()
		}
		c.Records[k] = cp
	}
	return c
}

// ---------------------------------------------------------------------------
// Cluster
// ---------------------------------------------------------------------------

// Replica is one member of the replicated store.
type Replica struct {
	ID    ReplicaID
	VV    VersionVector
	Store *Store
	Up    bool // read-eligible
}

// Cluster is a point-in-time view of the whole replication group.
type Cluster struct {
	N, R, W  int
	Replicas map[ReplicaID]*Replica
	// Pins are version vectors of active MVCC snapshot readers.  The newest
	// record visible at each pin is retained regardless of quorum safety.
	Pins []VersionVector
}

// IDs returns replica IDs in deterministic order.
func (c *Cluster) IDs() []ReplicaID {
	ids := make([]ReplicaID, 0, len(c.Replicas))
	for id := range c.Replicas {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	return ids
}

// Eligible returns the read-eligible replicas in deterministic order.
func (c *Cluster) Eligible() []ReplicaID {
	ids := c.IDs()
	out := make([]ReplicaID, 0, len(ids))
	for _, id := range ids {
		if c.Replicas[id].Up {
			out = append(out, id)
		}
	}
	return out
}

// Clone returns a deep copy.
func (c *Cluster) Clone() *Cluster {
	cc := &Cluster{N: c.N, R: c.R, W: c.W, Replicas: map[ReplicaID]*Replica{}}
	for id, r := range c.Replicas {
		cc.Replicas[id] = &Replica{ID: r.ID, VV: r.VV.Clone(), Store: r.Store.Clone(), Up: r.Up}
	}
	for _, p := range c.Pins {
		cc.Pins = append(cc.Pins, p.Clone())
	}
	return cc
}

func (c *Cluster) globalMax(key string) (Record, bool) {
	var best Record
	found := false
	for _, id := range c.IDs() {
		if m, ok := c.Replicas[id].Store.Max(key); ok {
			if !found || m.Stamp.Compare(best.Stamp) > 0 {
				best = m
				found = true
			}
		}
	}
	return best, found
}

func (c *Cluster) maxOver(key string, pred func(ReplicaID) bool) (Record, bool) {
	var best Record
	found := false
	for _, id := range c.IDs() {
		if !pred(id) {
			continue
		}
		if m, ok := c.Replicas[id].Store.Max(key); ok {
			if !found || m.Stamp.Compare(best.Stamp) > 0 {
				best = m
				found = true
			}
		}
	}
	return best, found
}

// ---------------------------------------------------------------------------
// Compaction planner
// ---------------------------------------------------------------------------

// Plan is the result of planning a compaction pass.
type Plan struct {
	// Keep[key][stampID] reports whether that logical version is retained.
	Keep map[string]map[string]bool
	// Reclaimed is the set of logical versions that may be physically removed.
	Reclaimed []Record
	// Retained is the complementary set.
	Retained []Record

	ReclaimedBytes int
	RetainedBytes  int

	// Fits reports whether RetainedBytes is within the caller's budget.
	Fits bool
	// Unsafe is set when lagging eligible replicas prevent reclamation of an
	// obsolete version, i.e. a newer version exists but not enough replicas
	// hold it yet.
	Unsafe bool
	// NoQuorum is set when fewer than R replicas are read-eligible.  In that
	// state the planner is conservative and reclaims nothing.
	NoQuorum bool
	// Lagging lists replicas that are behind the global maximum for some key.
	Lagging []ReplicaID
	// BlockedBy maps a key to the eligible replicas blocking reclamation.
	BlockedBy map[string][]ReplicaID
}

// Compute builds a safe compaction plan for the cluster.
func Compute(c *Cluster) *Plan {
	eligible := c.Eligible()
	m := len(eligible)
	need := m - c.R + 1

	p := &Plan{
		Keep:      map[string]map[string]bool{},
		BlockedBy: map[string][]ReplicaID{},
	}
	if m < c.R || need < 1 {
		p.Unsafe = true
		p.NoQuorum = true
		need = 0
	}

	// Union of all keys across all replicas.
	keys := map[string]bool{}
	for _, r := range c.Replicas {
		for k := range r.Store.Records {
			keys[k] = true
		}
	}
	keyList := make([]string, 0, len(keys))
	for k := range keys {
		keyList = append(keyList, k)
	}
	sort.Strings(keyList)

	lag := map[ReplicaID]bool{}

	for _, key := range keyList {
		p.Keep[key] = map[string]bool{}

		type entry struct {
			rec     Record
			holders []ReplicaID
		}
		byID := map[string]*entry{}
		var ids []string
		for _, rid := range c.IDs() {
			for _, rec := range c.Replicas[rid].Store.Records[key] {
				id := rec.Stamp.ID()
				e, ok := byID[id]
				if !ok {
					e = &entry{rec: rec}
					byID[id] = e
					ids = append(ids, id)
				}
				e.holders = append(e.holders, rid)
			}
		}
		// Process versions newest-first.  This lets the safety test use the
		// records that are actually retained, not the pre-compaction state.
		sort.Slice(ids, func(i, j int) bool {
			return byID[ids[i]].rec.Stamp.Compare(byID[ids[j]].rec.Stamp) > 0
		})

		// Snapshot pinning: newest version visible at each active pin.
		pinned := map[string]bool{}
		for _, pin := range c.Pins {
			var bestID string
			var bestStamp Stamp
			found := false
			for _, id := range ids {
				rec := byID[id].rec
				if !pin.Dominates(rec.Stamp.VV) {
					continue
				}
				if !found || rec.Stamp.Compare(bestStamp) > 0 {
					bestID, bestStamp, found = id, rec.Stamp, true
				}
			}
			if found {
				pinned[bestID] = true
			}
		}

		gmax, hasGlobal := c.globalMax(key)

		// Highest retained stamp per replica (rebuilt newest-first).
		retainedMax := map[ReplicaID]Stamp{}

		for _, id := range ids {
			e := byID[id]
			rec := e.rec

			if p.NoQuorum || pinned[id] {
				p.Keep[key][id] = true
				p.Retained = append(p.Retained, rec)
				p.RetainedBytes += rec.Size()
				for _, h := range e.holders {
					if mx, ok := retainedMax[h]; !ok || rec.Stamp.Compare(mx) > 0 {
						retainedMax[h] = rec.Stamp
					}
				}
				continue
			}

			// Count eligible replicas that already retain a strictly greater
			// version.  If that reaches M-R+1, every R-quorum has a witness
			// and this version can never be the winner of a read.
			cover := 0
			for _, el := range eligible {
				if mx, ok := retainedMax[el]; ok && mx.Compare(rec.Stamp) > 0 {
					cover++
				}
			}

			if cover >= need {
				p.Reclaimed = append(p.Reclaimed, rec)
				p.ReclaimedBytes += rec.Size()
			} else {
				p.Keep[key][id] = true
				p.Retained = append(p.Retained, rec)
				p.RetainedBytes += rec.Size()
				for _, h := range e.holders {
					if mx, ok := retainedMax[h]; !ok || rec.Stamp.Compare(mx) > 0 {
						retainedMax[h] = rec.Stamp
					}
				}
			}

			// Diagnose genuine lag: a superseded version that even the
			// pre-compaction replicas cannot jointly hide from R readers.
			if hasGlobal && rec.Stamp.Compare(gmax.Stamp) < 0 {
				var blockers []ReplicaID
				for _, el := range eligible {
					mx, ok := c.Replicas[el].Store.Max(key)
					if !ok || mx.Stamp.Compare(rec.Stamp) <= 0 {
						blockers = append(blockers, el)
					}
				}
				if len(blockers) >= c.R {
					p.Unsafe = true
					if _, exists := p.BlockedBy[key]; !exists {
						p.BlockedBy[key] = blockers
					}
					for _, b := range blockers {
						lag[b] = true
					}
				}
			}
		}
	}

	for id := range lag {
		p.Lagging = append(p.Lagging, id)
	}
	sort.Slice(p.Lagging, func(i, j int) bool { return p.Lagging[i] < p.Lagging[j] })
	return p
}

// ComputeFit plans a compaction and checks it against a disk budget in bytes.
func ComputeFit(c *Cluster, budget int) (*Plan, bool) {
	p := Compute(c)
	p.Fits = p.RetainedBytes <= budget
	return p, p.Fits
}

// Apply physically removes every reclaimed version from every replica.
// Versions kept by the plan are left untouched.
func (p *Plan) Apply(c *Cluster) {
	for _, r := range c.Replicas {
		for key, lst := range r.Store.Records {
			keep := p.Keep[key]
			out := make([]Record, 0, len(lst))
			for _, rec := range lst {
				if keep != nil && keep[rec.Stamp.ID()] {
					out = append(out, rec)
				}
			}
			if len(out) == 0 {
				delete(r.Store.Records, key)
			} else {
				r.Store.Records[key] = out
			}
		}
	}
}

// ---------------------------------------------------------------------------
// Rejoin recovery
// ---------------------------------------------------------------------------

// RecoveryPlan is the minimal set of records required to reconcile one
// replica that has rejoined the group.
type RecoveryPlan struct {
	Rejoined ReplicaID
	// Send are records the rejoined replica must adopt from the group.
	Send []Record
	// Push are records the rejoined replica holds that the group must adopt.
	Push []Record
	// NewVV is the merged version vector after the exchange.
	NewVV VersionVector
}

// Recovery computes the minimal reconciliation plan for a rejoining replica.
func Recovery(c *Cluster, rejoined ReplicaID) *RecoveryPlan {
	rp := &RecoveryPlan{Rejoined: rejoined, NewVV: VersionVector{}}

	clusterVV := VersionVector{}
	keys := map[string]bool{}
	for id, r := range c.Replicas {
		clusterVV = clusterVV.Merge(r.VV)
		for k := range r.Store.Records {
			keys[k] = true
		}
		_ = id
	}
	keyList := make([]string, 0, len(keys))
	for k := range keys {
		keyList = append(keyList, k)
	}
	sort.Strings(keyList)

	rej := c.Replicas[rejoined]
	if rej == nil {
		return rp
	}
	for _, key := range keyList {
		clusterMax, okC := c.maxOver(key, func(id ReplicaID) bool { return id != rejoined })
		rejMax, okR := rej.Store.Max(key)
		switch {
		case okC && (!okR || clusterMax.Stamp.Compare(rejMax.Stamp) > 0):
			rp.Send = append(rp.Send, clusterMax)
		case okR && !okC:
			rp.Push = append(rp.Push, rejMax)
		case okC && okR && rejMax.Stamp.Compare(clusterMax.Stamp) > 0:
			rp.Push = append(rp.Push, rejMax)
		}
	}
	rp.NewVV = clusterVV.Merge(rej.VV)
	return rp
}

// Apply merges the recovery plan into the cluster.
func (rp *RecoveryPlan) Apply(c *Cluster) {
	rej := c.Replicas[rp.Rejoined]
	if rej == nil {
		return
	}
	for _, rec := range rp.Send {
		rej.Store.Put(rec)
	}
	rej.VV = rej.VV.Merge(rp.NewVV)
	for _, rec := range rp.Push {
		for id, r := range c.Replicas {
			if id == rp.Rejoined {
				continue
			}
			r.Store.Put(rec)
			r.VV = r.VV.Merge(rp.NewVV)
		}
	}
}
