### `compaction_test.go`

```go
package quorumcompaction

import (
	"fmt"
	"math/rand"
	"sort"
	"testing"
)

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

// quorums enumerates every R-subset of eligible replicas.
func quorums(eligible []ReplicaID, r int) [][]ReplicaID {
	var res [][]ReplicaID
	cur := make([]ReplicaID, 0, r)
	var rec func(start int)
	rec = func(start int) {
		if len(cur) == r {
			cp := append([]ReplicaID(nil), cur...)
			res = append(res, cp)
			return
		}
		for i := start; i < len(eligible); i++ {
			cur = append(cur, eligible[i])
			rec(i + 1)
			cur = cur[:len(cur)-1]
		}
	}
	rec(0)
	return res
}

// readKey resolves a key from one quorum using LWW max.
func readKey(c *Cluster, q []ReplicaID, key string) (Record, bool) {
	var best Record
	found := false
	for _, id := range q {
		if m, ok := c.Replicas[id].Store.Max(key); ok {
			if !found || m.Stamp.Compare(best.Stamp) > 0 {
				best = m
				found = true
			}
		}
	}
	return best, found
}

func allKeys(c *Cluster) []string {
	set := map[string]bool{}
	for _, r := range c.Replicas {
		for k := range r.Store.Records {
			set[k] = true
		}
	}
	out := make([]string, 0, len(set))
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// assertReadPreserved verifies that no permitted quorum read changes after a
// plan is applied.  This is the core safety property.
func assertReadPreserved(t *testing.T, before, after *Cluster, eligible []ReplicaID) {
	t.Helper()
	qs := quorums(eligible, before.R)
	for _, key := range allKeys(before) {
		for _, q := range qs {
			b, okB := readKey(before, q, key)
			a, okA := readKey(after, q, key)
			if okB != okA {
				t.Fatalf("key %q quorum %v: presence changed %v -> %v", key, q, okB, okA)
			}
			if okB && !b.Stamp.Equal(a.Stamp) {
				t.Fatalf("key %q quorum %v: read changed %v -> %v", key, q, b.Stamp, a.Stamp)
			}
		}
	}
}

func vv(pairs ...interface{}) VersionVector {
	v := VersionVector{}
	for i := 0; i < len(pairs); i += 2 {
		v[ReplicaID(pairs[i].(string))] = uint64(pairs[i+1].(int))
	}
	return v
}

