// TestTombstoneNeverReclaimed verifies the anti-resurrection invariant: the
// latest version of a key is never reclaimed, even when it is a tombstone.
func TestTombstoneNeverReclaimed(t *testing.T) {
	c := &Cluster{N: 3, R: 2, W: 2, Replicas: map[ReplicaID]*Replica{}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: true}
	}
	old := Record{Key: "x", Value: []byte("v"), Stamp: Stamp{Origin: "A", Seq: 1, VV: vv("A", 1)}}
	tomb := Record{Key: "x", Tomb: true, Stamp: Stamp{Origin: "B", Seq: 2, VV: vv("A", 1, "B", 2)}}
	c.Replicas["A"].Store.Put(old)
	c.Replicas["B"].Store.Put(tomb)
	c.Replicas["C"].Store.Put(tomb)

	before := c.Clone()
	p := Compute(c)
	if p.NoQuorum {
		t.Fatal("expected a quorum")
	}
	if p.Keep["x"][tomb.Stamp.ID()] != true {
		t.Fatalf("latest tombstone must be retained, plan=%+v", p.Keep["x"])
	}
	if p.Keep["x"][old.Stamp.ID()] {
		t.Fatalf("obsolete value should be reclaimed, plan=%+v", p.Keep["x"])
	}
	p.Apply(c)
	assertReadPreserved(t, before, c, c.Eligible())
}

// TestLaggingReplicaBlocksReclamation verifies that a replica which has not
// received the tombstone blocks reclamation and is reported.
func TestLaggingReplicaBlocksReclamation(t *testing.T) {
	c := &Cluster{N: 3, R: 2, W: 2, Replicas: map[ReplicaID]*Replica{}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: true}
	}
	old := Record{Key: "x", Value: []byte("v"), Stamp: Stamp{Origin: "A", Seq: 1, VV: vv("A", 1)}}
	tomb := Record{Key: "x", Tomb: true, Stamp: Stamp{Origin: "B", Seq: 2, VV: vv("A", 1, "B", 2)}}
	// A and C still hold the value; only B has the tombstone.
	c.Replicas["A"].Store.Put(old)
	c.Replicas["B"].Store.Put(tomb)
	c.Replicas["C"].Store.Put(old)

	p := Compute(c)
	if p.Keep["x"][old.Stamp.ID()] != true {
		t.Fatal("obsolete value must be retained while a quorum of readers can still see it")
	}
	if !p.Unsafe {
		t.Fatal("expected Unsafe to be detected")
	}
	blockers := p.BlockedBy["x"]
	if len(blockers) != 2 {
		t.Fatalf("expected 2 blockers, got %v", blockers)
	}
	if len(p.Lagging) != 2 {
		t.Fatalf("expected 2 lagging replicas, got %v", p.Lagging)
	}
}

// TestSnapshotPinRetainsHistory verifies MVCC snapshot readers keep pinned
// versions alive even when every replica has moved on.
func TestSnapshotPinRetainsHistory(t *testing.T) {
	c := &Cluster{N: 3, R: 2, W: 2, Replicas: map[ReplicaID]*Replica{}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: true}
	}
	v1 := Record{Key: "x", Value: []byte("one"), Stamp: Stamp{Origin: "A", Seq: 1, VV: vv("A", 1)}}
	v2 := Record{Key: "x", Value: []byte("two"), Stamp: Stamp{Origin: "A", Seq: 2, VV: vv("A", 2)}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id].Store.Put(v1)
		c.Replicas[id].Store.Put(v2)
	}
	// A reader is pinned to the v1 era.
	c.Pins = []VersionVector{vv("A", 1)}

	p := Compute(c)
	if p.Keep["x"][v1.Stamp.ID()] != true {
		t.Fatal("snapshot-pinned version must be retained")
	}
	if p.Keep["x"][v2.Stamp.ID()] != true {
		t.Fatal("latest version must be retained")
	}
	if p.ReclaimedBytes != 0 {
		t.Fatalf("nothing should be reclaimed, got %d bytes", p.ReclaimedBytes)
	}

	// Without the pin, v1 is reclaimable.
	c2 := c.Clone()
	c2.Pins = nil
	p2 := Compute(c2)
	if p2.Keep["x"][v1.Stamp.ID()] {
		t.Fatal("without a pin the old version should be reclaimed")
	}
	if p2.ReclaimedBytes == 0 {
		t.Fatal("expected reclamation")
	}
}

// TestRejoinMinimalRecovery verifies that a rejoining replica converges with a
// minimal, one-record-per-key recovery plan.
func TestRejoinMinimalRecovery(t *testing.T) {
	c := &Cluster{N: 3, R: 2, W: 2, Replicas: map[ReplicaID]*Replica{}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: true}
	}
	base := Record{Key: "x", Value: []byte("base"), Stamp: Stamp{Origin: "A", Seq: 1, VV: vv("A", 1)}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id].Store.Put(base)
	}
	// Ground truth: the fully-replicated converged state.
	ground := c.Clone()

	// B goes down, A and C advance.
	c.Replicas["B"].Up = false
	w2 := Record{Key: "x", Value: []byte("two"), Stamp: Stamp{Origin: "A", Seq: 2, VV: vv("A", 2)}}
	g2 := Record{Key: "y", Value: []byte("new"), Tomb: true, Stamp: Stamp{Origin: "C", Seq: 1, VV: vv("A", 2, "C", 1)}}
	c.Replicas["A"].Store.Put(w2)
	c.Replicas["C"].Store.Put(g2)
	for _, id := range []ReplicaID{"A", "B", "C"} {
		ground.Replicas[id].Store.Put(w2)
		ground.Replicas[id].Store.Put(g2)
	}

	// Compact while B is down.
	p := Compute(c)
	p.Apply(c)

	// B rejoins and recovery runs before it serves reads.
	c.Replicas["B"].Up = true
	rp := Recovery(c, "B")
	rp.Apply(c)

	assertReadPreserved(t, ground, c, c.Eligible())

	if len(rp.Send) != 2 {
		t.Fatalf("expected 2 records to send (x and y), got %d: %+v", len(rp.Send), rp.Send)
	}
}

