// randomized brute-force safety test
// ---------------------------------------------------------------------------

func TestRandomizedQuorumSafety(t *testing.T) {
	rng := rand.New(rand.NewSource(20261005))
	for iter := 0; iter < 3000; iter++ {
		c := randomCluster(rng)
		before := c.Clone()
		eligible := c.Eligible()

		// Apply snapshot pins sometimes.
		if rng.Intn(3) == 0 {
			pin := VersionVector{}
			for _, id := range c.IDs() {
				pin[id] = uint64(rng.Intn(4))
			}
			c.Pins = []VersionVector{pin}
			before.Pins = []VersionVector{pin.Clone()}
		}

		p := Compute(c)
		p.Apply(c)
		assertReadPreserved(t, before, c, eligible)

		// After compaction, applying again must be a no-op and remain safe.
		p2 := Compute(c)
		if len(p2.Reclaimed) != 0 {
			// A second pass may still reclaim versions that only became safe
			// after the first pass; applying it must not change reads.
			c2 := c.Clone()
			p2.Apply(c2)
			assertReadPreserved(t, c, c2, c.Eligible())
		}

		// The global maximum per key must always survive.
		for _, key := range allKeys(before) {
			g, ok := before.globalMax(key)
			if !ok {
				continue
			}
			after, ok2 := c.globalMax(key)
			if !ok2 || !after.Stamp.Equal(g.Stamp) {
				t.Fatalf("iter %d: global max for %q was reclaimed", iter, key)
			}
		}
	}
}

func randomCluster(rng *rand.Rand) *Cluster {
	n := 3 + rng.Intn(3) // 3..5
	R := 2 + rng.Intn(2)
	if R > n {
		R = n
	}
	c := &Cluster{N: n, R: R, W: n - R + 1, Replicas: map[ReplicaID]*Replica{}}
	ids := make([]ReplicaID, n)
	for i := 0; i < n; i++ {
		id := ReplicaID(fmt.Sprintf("r%d", i))
		ids[i] = id
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: rng.Intn(5) != 0}
	}
	// Guarantee at least R eligible replicas so a quorum can exist most of the
	// time; leave the rest random.
	nUp := 0
	for _, r := range c.Replicas {
		if r.Up {
			nUp++
		}
	}
	for i := 0; nUp < R && i < n; i++ {
		if !c.Replicas[ids[i]].Up {
			c.Replicas[ids[i]].Up = true
			nUp++
		}
	}

	nkeys := 1 + rng.Intn(3)
	for ki := 0; ki < nkeys; ki++ {
		key := fmt.Sprintf("k%d", ki)
		nrec := rng.Intn(4)
		for v := 0; v < nrec; v++ {
			origin := ids[rng.Intn(n)]
			seq := uint64(rng.Intn(3) + 1)
			vec := VersionVector{origin: seq}
			for j := 0; j < n; j++ {
				if rng.Intn(2) == 0 {
					if _, ok := vec[ids[j]]; !ok {
						vec[ids[j]] = uint64(rng.Intn(3))
					}
				}
			}
			rec := Record{
				Key:   key,
				Value: []byte(fmt.Sprintf("%s-%d-%d", origin, seq, v)),
				Tomb:  rng.Intn(4) == 0,
				Stamp: Stamp{Origin: origin, Seq: seq, VV: vec},
			}
			placements := 0
			for _, id := range ids {
				if rng.Intn(2) == 0 {
					c.Replicas[id].Store.Put(rec)
					placements++
				}
			}
			if placements == 0 {
				c.Replicas[ids[rng.Intn(n)]].Store.Put(rec)
			}
		}
	}
	return c
}

