func TestBudgetAndFit(t *testing.T) {
	c := &Cluster{N: 3, R: 2, W: 2, Replicas: map[ReplicaID]*Replica{}}
	for _, id := range []ReplicaID{"A", "B", "C"} {
		c.Replicas[id] = &Replica{ID: id, VV: VersionVector{}, Store: NewStore(), Up: true}
	}
	for i := 0; i < 10; i++ {
		rec := Record{Key: "x", Value: []byte("0123456789"), Stamp: Stamp{Origin: "A", Seq: uint64(i + 1), VV: vv("A", i+1)}}
		for _, id := range []ReplicaID{"A", "B", "C"} {
			c.Replicas[id].Store.Put(rec)
		}
	}
	// Only the latest version needs to survive: every quorum contains a
	// replica holding it, so all older versions are safely reclaimable.
	p := Compute(c)
	if len(p.Reclaimed) != 9 {
		t.Fatalf("expected 9 reclaimed, got %d", len(p.Reclaimed))
	}
	if p.ReclaimedBytes == 0 || p.RetainedBytes == 0 {
		t.Fatal("byte accounting failed")
	}
	// A budget equal to the safe retained size fits; a tiny budget does not.
	if _, ok := ComputeFit(c, p.RetainedBytes); !ok {
		t.Fatal("budget should fit exactly")
	}
	if _, ok := ComputeFit(c, 1); ok {
		t.Fatal("tiny budget must not fit after safe compaction")
	}

	// Blocked scenario must report Unsafe and still preserve reads.
	c2 := c.Clone()
	// A and C fall back to an old version, B keeps the latest.
	old := Record{Key: "x", Value: []byte("old"), Stamp: Stamp{Origin: "A", Seq: 1, VV: vv("A", 1)}}
	c2.Replicas["A"].Store.Put(old)
	c2.Replicas["C"].Store.Put(old)
	// Remove newer versions from A and C.
	for _, id := range []ReplicaID{"A", "C"} {
		var kept []Record
		for _, r := range c2.Replicas[id].Store.Records["x"] {
			if r.Stamp.Compare(old.Stamp) <= 0 {
				kept = append(kept, r)
			}
		}
		c2.Replicas[id].Store.Records["x"] = kept
	}
	p2 := Compute(c2)
	if !p2.Unsafe {
		t.Fatal("expected Unsafe when replicas lag behind")
	}
	before := c2.Clone()
	p2.Apply(c2)
	assertReadPreserved(t, before, c2, c2.Eligible())
}
